insert into public.site_settings (key,locale,value_json) values ('global','tr','{"contact":{},"social":{},"seo":{"defaultTitle":"SDKONGRE | Kongre ve Etkinlik Organizasyonu","defaultDescription":"Kongre, toplantı, sempozyum, kurumsal etkinlik ve dijital organizasyon süreçlerinde uçtan uca profesyonel çözümler."},"hero":{"poster":"/fallback/hero-poster.svg","desktopVideo":"","mobileVideo":""},"homeValues":[{"number":"01","title":"Kusursuz Planlama","description":"Her ayrıntıyı önceden düşünür, olası riskleri etkinlik başlamadan yönetiriz.","icon":"calendar-check"},{"number":"02","title":"Uluslararası Standart","description":"Yerel deneyimi global hizmet anlayışı ve kurumsal süreç disipliniyle birleştiririz.","icon":"globe"},{"number":"03","title":"Deneyim Odaklı","description":"Her temas noktasını katılımcılar için akıcı ve hatırlanabilir bir deneyime dönüştürürüz.","icon":"sparkles"},{"number":"04","title":"Tek Noktadan Yönetim","description":"Planlama, kayıt, teknik operasyon, konaklama ve koordinasyonu tek merkezden yürütürüz.","icon":"workflow"},{"number":"05","title":"Güven Veren Çözümler","description":"Şeffaf iletişim, profesyonel ekip ve sürdürülebilir kalite anlayışıyla ilerleriz.","icon":"shield-check"}]}'::jsonb) on conflict (key,locale) do update set value_json=excluded.value_json, updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('about','tr','Hakkımızda','hakkimizda','KURUMSAL','Organizasyon Yönetiminde Güvenilir Çözüm Ortağınız','{"headline":"Organizasyon Yönetiminde Güvenilir Çözüm Ortağınız","paragraphs":["SD Kongre, kongre, sempozyum, toplantı, lansman, fuar, kurumsal etkinlik ve seyahat organizasyonlarında uçtan uca hizmet sunan profesyonel bir organizasyon ve etkinlik yönetim şirketidir.","Kurulduğumuz günden bu yana temel amacımız; kurumların organizasyon süreçlerini daha verimli, daha kontrollü ve daha başarılı hale getirmektir. Organizasyonların yalnızca etkinlik günü değil, fikir aşamasından sonuç raporuna kadar geçen tüm süreçlerinin profesyonel şekilde yönetilmesi gerektiğine inanıyoruz.","Bu anlayışla; planlama, bütçe yönetimi, tedarikçi koordinasyonu, konaklama çözümleri, dijital kayıt sistemleri, saha operasyonları ve raporlama süreçlerini tek merkezden yönetiyor, müşterilerimize zaman ve maliyet avantajı sağlıyoruz.","Kamu kurumlarından özel sektöre, meslek örgütlerinden akademik kuruluşlara kadar geniş bir yelpazede hizmet verirken her projeyi kendi dinamikleri içerisinde değerlendiriyor ve kurumlara özel çözümler geliştiriyoruz.","SD Kongre olarak biz, yalnızca organizasyon düzenleyen bir firma değil; kurumların hedeflerine ulaşmasını sağlayan stratejik bir çözüm ortağı olmayı hedefliyoruz."]}'::jsonb,'published'::public.content_status,'{"title":"Hakkımızda","description":"Organizasyon Yönetiminde Güvenilir Çözüm Ortağınız"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('story','tr','Hikayemiz','hikayemiz','KURUMSAL','Bir Organizasyondan Daha Fazlası','{"headline":"Bir Organizasyondan Daha Fazlası","paragraphs":["SD Kongre''nin hikayesi, profesyonel organizasyon yönetimine duyulan ihtiyaçtan doğdu.","Kuruluşumuzun temelinde; kurumların farklı tedarikçilerle çalışırken yaşadığı koordinasyon sorunlarını, bütçe kontrolündeki zorlukları ve operasyonel yükleri azaltma fikri bulunmaktadır.","İlk günden itibaren yalnızca etkinlik organizasyonu gerçekleştirmeyi değil, süreç yönetimi konusunda fark yaratmayı hedefledik. Bu nedenle organizasyon sektörünü teknoloji, raporlama ve veri yönetimiyle birleştirerek daha ölçülebilir ve daha sürdürülebilir bir yapı oluşturduk.","Yıllar içerisinde gerçekleştirdiğimiz toplantılar, kongreler, sempozyumlar, eğitim programları, kurumsal etkinlikler ve lansmanlar sayesinde sektörde önemli bir deneyim birikimi elde ettik.","Bugün geldiğimiz noktada SD Kongre; planlama gücü, güçlü operasyon ağı, dijital altyapıları ve uzman ekibiyle Türkiye''nin farklı şehirlerinde başarılı organizasyonlara imza atan güvenilir bir marka haline gelmiştir.","Ancak bizim için başarı, tamamlanan organizasyon sayısından çok müşterilerimizin bize yeniden güvenmesi ve bizi tavsiye etmesidir."]}'::jsonb,'published'::public.content_status,'{"title":"Hikayemiz","description":"Bir Organizasyondan Daha Fazlası"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('mission','tr','Misyon','misyon','KURUMSAL','Kurumların ihtiyaçlarına özel, yenilikçi ve sürdürülebilir organizasyon çözümleri geliştirerek her projeyi yüksek kalite standartlarında hayata geçirmek.','{"headline":"Kurumların ihtiyaçlarına özel, yenilikçi ve sürdürülebilir organizasyon çözümleri geliştirerek her projeyi yüksek kalite standartlarında hayata geçirmek.","paragraphs":["Kurumların ihtiyaçlarına özel, yenilikçi ve sürdürülebilir organizasyon çözümleri geliştirerek her projeyi yüksek kalite standartlarında hayata geçirmek.","Planlama, koordinasyon, teknoloji ve operasyon gücümüzü bir araya getirerek müşterilerimize maksimum verimlilik, minimum operasyonel yük ve ölçülebilir başarı sunmak.","Organizasyon süreçlerinde güvenilir bir iş ortağı olarak müşterilerimizin hedeflerine ulaşmalarına katkı sağlamak."]}'::jsonb,'published'::public.content_status,'{"title":"Misyon","description":"Kurumların ihtiyaçlarına özel, yenilikçi ve sürdürülebilir organizasyon çözümleri geliştirerek her projeyi yüksek kalite standartlarında hayata geçirmek."}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('vision','tr','Vizyon','vizyon','KURUMSAL','Kongre ve etkinlik yönetimi sektöründe yenilikçi yaklaşımı, teknolojik altyapıları ve operasyonel mükemmeliyetiyle Türkiye''nin en güçlü ve en çok tercih edilen organizasyon yönetim markalarından biri olmak.','{"headline":"Kongre ve etkinlik yönetimi sektöründe yenilikçi yaklaşımı, teknolojik altyapıları ve operasyonel mükemmeliyetiyle Türkiye''nin en güçlü ve en çok tercih edilen organizasyon yönetim markalarından biri olmak.","paragraphs":["Kongre ve etkinlik yönetimi sektöründe yenilikçi yaklaşımı, teknolojik altyapıları ve operasyonel mükemmeliyetiyle Türkiye''nin en güçlü ve en çok tercih edilen organizasyon yönetim markalarından biri olmak.","Ulusal ve uluslararası ölçekte yürütülen projelerde kalite, güven ve sürdürülebilirlik denildiğinde akla gelen ilk çözüm ortağı haline gelmek."]}'::jsonb,'published'::public.content_status,'{"title":"Vizyon","description":"Kongre ve etkinlik yönetimi sektöründe yenilikçi yaklaşımı, teknolojik altyapıları ve operasyonel mükemmeliyetiyle Türkiye''nin en güçlü ve en çok tercih edilen organizasyon yönetim markalarından biri olmak."}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('values','tr','Değerlerimiz','degerlerimiz','KURUMSAL','Değerlerimiz','{"headline":"Değerlerimiz","paragraphs":[],"values":[{"title":"Güven","description":"İşimizin temelinde güven yer alır. Verdiğimiz sözleri zamanında yerine getirir, süreçleri şeffaf biçimde yönetir ve müşterilerimizle uzun vadeli ilişkiler kurarız."},{"title":"Şeffaflık","description":"Bütçe, planlama, satın alma ve raporlama süreçlerinin tamamında açık iletişim prensibiyle hareket ederiz."},{"title":"Profesyonellik","description":"Her organizasyona aynı ciddiyet ve sorumluluk bilinciyle yaklaşırız."},{"title":"Yenilikçilik","description":"Teknolojik gelişmeleri yakından takip eder, organizasyon süreçlerine yenilikçi çözümler entegre ederiz."},{"title":"Sürdürülebilirlik","description":"Planlama ve operasyon süreçlerinde kaynakların verimli kullanımını esas alırız."},{"title":"Müşteri Odaklılık","description":"Başarımızın merkezinde müşteri memnuniyeti bulunmaktadır."}]}'::jsonb,'published'::public.content_status,'{"title":"Değerlerimiz","description":"Değerlerimiz"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('why-us','tr','Neden Biz','neden-biz','NEDEN BİZ','Her Detayı Yönetiyor, Her Süreci Kontrol Ediyoruz','{"headline":"Her Detayı Yönetiyor, Her Süreci Kontrol Ediyoruz","paragraphs":["Bir organizasyonun başarısı yalnızca etkinlik günündeki kusursuz uygulamayla değil, öncesinde yapılan doğru planlama ve profesyonel koordinasyonla mümkündür.","SD Kongre olarak müşterilerimize yalnızca organizasyon hizmeti değil, bütüncül proje yönetimi sunuyoruz."],"items":[{"title":"Tek Noktadan Yönetim","description":"Farklı tedarikçiler, farklı ekipler ve ayrı koordinasyon süreçleri yerine tüm organizasyon tek merkezden yönetilir.","icon":"network"},{"title":"Türkiye Genelinde Operasyon Gücü","description":"Ankara merkezli yapımız ve geniş çözüm ortağı ağımız sayesinde ülke genelinde aynı kalite standartlarında hizmet veriyoruz.","icon":"map"},{"title":"Teknoloji Destekli Süreçler","description":"Online kayıt sistemleri, QR kod uygulamaları, dijital davet çözümleri ve raporlama sistemleriyle süreçleri daha verimli yönetiyoruz.","icon":"cpu"},{"title":"Şeffaf Bütçe Yönetimi","description":"Harcamaların her aşaması kontrol altında tutulur ve düzenli raporlanır.","icon":"wallet"},{"title":"Deneyimli Uzman Kadro","description":"Alanında uzman proje yöneticileri, operasyon ekipleri ve teknik destek personelleri ile tüm süreçler profesyonel şekilde yürütülür.","icon":"users"},{"title":"Ölçülebilir Sonuçlar","description":"Her organizasyon sonunda detaylı raporlama sunularak yatırımın geri dönüşü analiz edilir.","icon":"chart"}]}'::jsonb,'published'::public.content_status,'{"title":"Neden Biz","description":"Her Detayı Yönetiyor, Her Süreci Kontrol Ediyoruz"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Lansman ve Kurumsal Etkinlikler','lansman-ve-kurumsal-etkinlikler','Yeni ürün, hizmet veya marka tanıtımlarında hedef kitleniz üzerinde güçlü ve kalıcı etkiler bırakacak profesyonel etkinlikler tasarlıyoruz.','{"paragraphs":["Etkinlik konseptinin oluşturulmasından mekan seçimine, sahne tasarımından teknik altyapıya, davet süreçlerinden medya koordinasyonuna kadar tüm organizasyon detaylarını yönetiyoruz.","Markanızın kurumsal kimliğini ve mesajını doğru şekilde yansıtan etkinlik deneyimleri sunuyoruz."],"features":[]}'::jsonb,'sparkles',1,'published'::public.content_status,'{"title":"Lansman ve Kurumsal Etkinlikler","description":"Yeni ürün, hizmet veya marka tanıtımlarında hedef kitleniz üzerinde güçlü ve kalıcı etkiler bırakacak profesyonel etkinlikler tasarlıyoruz."}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
