insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Seyahat ve Konaklama Yönetimi','seyahat-ve-konaklama-yonetimi','Katılımcı, konuşmacı ve davetlilerin tüm seyahat süreçlerini profesyonel biçimde planlıyoruz.','{"paragraphs":[],"features":["Uçak bileti organizasyonu","Otel rezervasyonları","VIP konaklama çözümleri","Grup rezervasyonları","Karşılama hizmetleri","Transfer koordinasyonu"]}'::jsonb,'hotel',6,'published'::public.content_status,'{"title":"Seyahat ve Konaklama Yönetimi","description":"Katılımcı, konuşmacı ve davetlilerin tüm seyahat süreçlerini profesyonel biçimde planlıyoruz."}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
