insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','Veri ve Raporlama Sistemleri','veri-ve-raporlama-sistemleri','Etkinlik sonunda yalnızca organizasyonu tamamlamıyor, ölçülebilir sonuçlar da sunuyoruz.','{"paragraphs":[],"features":["Katılımcı analizleri","Katılım oranları","Operasyon raporları","Bütçe raporları","Performans değerlendirmeleri"]}'::jsonb,'chart',6,'published'::public.content_status,'{"title":"Veri ve Raporlama Sistemleri","description":"Etkinlik sonunda yalnızca organizasyonu tamamlamıyor, ölçülebilir sonuçlar da sunuyoruz."}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','Veri Güvenliği ve Merkezi Yönetim','veri-guvenligi-ve-merkezi-yonetim','Tüm katılımcı verileri güvenli sunucularda saklanmakta ve KVKK hükümlerine uygun şekilde işlenmektedir.','{"paragraphs":["Kurumsal verileriniz en yüksek güvenlik standartlarıyla korunmaktadır."],"features":[]}'::jsonb,'shield',7,'published'::public.content_status,'{"title":"Veri Güvenliği ve Merkezi Yönetim","description":"Tüm katılımcı verileri güvenli sunucularda saklanmakta ve KVKK hükümlerine uygun şekilde işlenmektedir."}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.process_steps (locale,step_key,title,subtitle,description,content_json,icon,order_no,status) values ('tr','brief','BRIEF','İhtiyaçların Doğru Analizi ile Sağlam Bir Başlangıç','Her başarılı organizasyonun temelinde doğru bir ihtiyaç analizi bulunur. Bu nedenle proje sürecine başlamadan önce kurumun beklentilerini, hedeflerini ve organizasyonun genel kapsamını detaylı şekilde değerlendiriyoruz.','{"number":"01","items":["Organizasyonun amacı ve hedefleri belirlenir.","Hedef katılımcı profili analiz edilir.","Etkinliğin türü, kapsamı ve büyüklüğü netleştirilir.","Tarih ve lokasyon alternatifleri değerlendirilir.","Kurumsal beklentiler ve özel talepler kayıt altına alınır.","Operasyonel ihtiyaçlar ve olası riskler belirlenir.","Bütçe çerçevesi ve mali beklentiler analiz edilir."],"groups":[],"closing":"Gerçekleştirdiğimiz detaylı brief toplantıları sayesinde organizasyonun yol haritasını oluşturarak sonraki süreçlerin eksiksiz ilerlemesini sağlıyoruz.","outputs":["İhtiyaç Analiz Raporu","Hedef Kitle Belirleme","Organizasyon Kapsamı","İlk Operasyon Taslağı","Ön Bütçe Çalışması"]}'::jsonb,'workflow',1,'published'::public.content_status) on conflict (locale,step_key) do update set title=excluded.title,subtitle=excluded.subtitle,description=excluded.description,content_json=excluded.content_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,updated_at=now();
insert into public.process_steps (locale,step_key,title,subtitle,description,content_json,icon,order_no,status) values ('tr','planlama','PLANLAMA','Her Detayın Önceden Tasarlandığı Profesyonel Hazırlık Süreci','Planlama aşaması, organizasyonun başarısını doğrudan etkileyen en kritik süreçlerden biridir. Bu aşamada tüm operasyonel ve teknik detaylar sistematik şekilde oluşturulur.','{"number":"02","items":["Organizasyon takvimini hazırlar.","Görev ve sorumluluk dağılımlarını belirler.","Mekân planlamasını yapar.","Teknik altyapı ihtiyaçlarını tespit eder.","Konaklama ve ulaşım planlarını oluşturur.","Tedarikçi ve çözüm ortaklarını belirler.","Risk ve kriz yönetim planlarını hazırlar.","Satın alma süreçlerini planlar.","Kaynak ve bütçe yönetimini oluşturur."],"groups":[],"closing":"Planlama sürecinde tüm paydaşlar arasında koordinasyon sağlanarak organizasyon gününe kadar gerçekleşecek her adım netleştirilir.","outputs":["Operasyon Takvimi","Görev ve Sorumluluk Planı","Bütçe Planı","Risk Yönetim Planı","Teknik Altyapı Planlaması","Lojistik ve Transfer Planı"]}'::jsonb,'workflow',2,'published'::public.content_status) on conflict (locale,step_key) do update set title=excluded.title,subtitle=excluded.subtitle,description=excluded.description,content_json=excluded.content_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,updated_at=now();
insert into public.process_steps (locale,step_key,title,subtitle,description,content_json,icon,order_no,status) values ('tr','teklif','TEKLİF','Şeffaf, Anlaşılır ve İhtiyaca Özel Çözümler','Planlama çalışmaları tamamlandıktan sonra organizasyonun tüm kapsamını içeren detaylı teklif dosyası hazırlanır.','{"number":"03","items":["Hizmet kapsamı detaylandırılır.","Alternatif uygulama senaryoları hazırlanır.","Bütçe kalemleri açık şekilde listelenir.","Operasyonel süreçler tanımlanır.","Teknik ihtiyaçlar belirlenir.","İnsan kaynağı planlaması sunulur.","Zaman çizelgesi oluşturulur."],"groups":[],"closing":"Amacımız yalnızca maliyet sunmak değil; kurumun ihtiyaçlarına uygun, maksimum verim sağlayacak sürdürülebilir bir çözüm modeli geliştirmektir.","outputs":["Organizasyon Konsepti","Hizmet Kapsamı","Teknik ve Operasyonel Çözümler","Personel Planlaması","Konaklama ve Seyahat Yönetimi","Detaylı Bütçe Analizi","Uygulama Takvimi"]}'::jsonb,'workflow',3,'published'::public.content_status) on conflict (locale,step_key) do update set title=excluded.title,subtitle=excluded.subtitle,description=excluded.description,content_json=excluded.content_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,updated_at=now();
insert into public.process_steps (locale,step_key,title,subtitle,description,content_json,icon,order_no,status) values ('tr','onay','ONAY','Sürecin Netleştirildiği ve Projenin Başlatıldığı Aşama','Teklif değerlendirme sürecinin ardından proje detayları karşılıklı olarak gözden geçirilir ve son hali oluşturulur.','{"number":"04","items":["Hizmet kapsamı kesinleştirilir.","Bütçe kalemleri onaylanır.","Uygulama takvimi netleştirilir.","Tedarikçi seçimleri tamamlanır.","Operasyon ekibi oluşturulur.","İş planları kesinleştirilir.","İletişim ve koordinasyon süreçleri tanımlanır."],"groups":[],"closing":"Onay aşaması sayesinde tüm paydaşlar aynı hedef doğrultusunda hareket eder ve uygulama süreci kontrollü şekilde başlatılır.","outputs":["Onaylanmış Proje Planı","Kesin Bütçe Çalışması","Operasyon Organizasyon Şeması","Uygulama Takvimi","Tedarikçi ve Çözüm Ortakları Listesi"]}'::jsonb,'workflow',4,'published'::public.content_status) on conflict (locale,step_key) do update set title=excluded.title,subtitle=excluded.subtitle,description=excluded.description,content_json=excluded.content_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,updated_at=now();
insert into public.process_steps (locale,step_key,title,subtitle,description,content_json,icon,order_no,status) values ('tr','operasyon','OPERASYON','Organizasyonun Sahadaki Kusursuz Yönetimi','Operasyon süreci, hazırlıkların gerçeğe dönüştüğü ve organizasyonun tüm detaylarının uygulandığı aşamadır. SD Kongre operasyon ekibi etkinlik öncesi, etkinlik süresince ve etkinlik sonrasında tüm süreçlerin koordinasyonunu sağlar.','{"number":"05","items":[],"groups":[{"title":"Etkinlik Öncesi","items":["Mekân hazırlıkları gerçekleştirilir.","Teknik ekipman kurulumları yapılır.","Kayıt alanları oluşturulur.","Yaka kartları ve materyaller hazırlanır.","Transfer planları uygulanır.","Konaklama organizasyonları tamamlanır."]},{"title":"Etkinlik Sırasında","items":["Katılımcı kayıt süreçleri yönetilir.","Konuşmacı koordinasyonu sağlanır.","Teknik ekipler yönetilir.","Protokol organizasyonu yürütülür.","Sahne ve program akışı takip edilir.","Anlık kriz ve risk yönetimi gerçekleştirilir."]},{"title":"Etkinlik Sonrasında","items":["Kapanış operasyonları tamamlanır.","Demontaj süreçleri yürütülür.","Katılımcı verileri konsolide edilir.","Tedarikçi kapanış işlemleri gerçekleştirilir."]}],"closing":"","outputs":["Tek Merkezden Koordinasyon","Anlık Süreç Takibi","Profesyonel Saha Yönetimi","Kriz ve Risk Yönetimi","Katılımcı Memnuniyeti Odaklı Hizmet","Tam Operasyonel Kontrol"]}'::jsonb,'workflow',5,'published'::public.content_status) on conflict (locale,step_key) do update set title=excluded.title,subtitle=excluded.subtitle,description=excluded.description,content_json=excluded.content_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,updated_at=now();
insert into public.process_steps (locale,step_key,title,subtitle,description,content_json,icon,order_no,status) values ('tr','raporlama','RAPORLAMA','Ölçülebilir Sonuçlar ve Stratejik Değerlendirme','Bir organizasyonun başarısı yalnızca tamamlanmış olmasıyla değil, elde edilen çıktılarla değerlendirilir. Bu nedenle proje sonunda kapsamlı raporlama ve analiz çalışmaları gerçekleştiriyoruz.','{"number":"06","items":["Katılımcı istatistikleri hazırlanır.","Kayıt ve katılım oranları analiz edilir.","Operasyon performansı değerlendirilir.","Bütçe gerçekleşme raporları oluşturulur.","Tedarikçi performans analizleri yapılır.","Memnuniyet anketleri değerlendirilir.","Güçlü yönler ve geliştirme alanları belirlenir.","Gelecek organizasyonlar için öneriler hazırlanır."],"groups":[],"closing":"Sunulan raporlar sayesinde kurumlar organizasyon yatırımlarının çıktılarını somut verilerle değerlendirebilir ve gelecekteki projelerini daha verimli planlayabilir.","outputs":["Katılımcı ve Kayıt Analizleri","Etkinlik Performans Değerlendirmesi","Bütçe Gerçekleşme Raporu","Operasyon Sonuç Raporu","Memnuniyet ve Geri Bildirim Analizi","Fotoğraf ve Medya Arşivi","Yönetici Özet Raporu","Gelecek Dönem Önerileri"]}'::jsonb,'workflow',6,'published'::public.content_status) on conflict (locale,step_key) do update set title=excluded.title,subtitle=excluded.subtitle,description=excluded.description,content_json=excluded.content_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,updated_at=now();
insert into public.legal_documents (document_key,locale,title,slug,body_json,version,effective_date,status,seo_json,published_at) values ('privacy-notice','tr','KVKK Aydınlatma Metni','aydinlatma-metni','{"headline":"Kişisel Verilerin Korunması ve İşlenmesine İlişkin Aydınlatma Metni","sections":[{"title":null,"paragraphs":["SD Kongre Organizasyon ve Etkinlik Yönetimi (\"SD Kongre\") olarak özel hayatın gizliliğine ve kişisel verilerin korunmasına önem vermekteyiz. Bu kapsamda, 6698 Sayılı Kişisel Verilerin Korunması Kanunu (\"KVKK\") uyarınca veri sorumlusu sıfatıyla kişisel verilerinizi aşağıda belirtilen çerçevede işlemekteyiz."]},{"title":"İşlenen Kişisel Veriler","bullets":["Ad, soyad","T.C. Kimlik numarası","Telefon numarası","E-posta adresi","Kurum ve görev bilgileri","Konaklama ve seyahat bilgileri","Katılımcı kayıt bilgileri","Finansal ve faturalandırma bilgileri","IP adresi ve internet kullanım verileri","Fotoğraf ve video kayıtları"]},{"title":"Kişisel Verilerin İşlenme Amaçları","paragraphs":["Kişisel verileriniz aşağıdaki amaçlarla işlenebilmektedir."],"bullets":["Kongre, toplantı ve etkinlik organizasyonlarının yürütülmesi","Katılımcı kayıt süreçlerinin yönetilmesi","Konaklama ve ulaşım hizmetlerinin sağlanması","Bilgilendirme ve duyuru faaliyetlerinin gerçekleştirilmesi","Sözleşmesel yükümlülüklerin yerine getirilmesi","Finans ve muhasebe süreçlerinin yürütülmesi","Müşteri memnuniyetinin artırılması","Yasal yükümlülüklerin yerine getirilmesi","Bilgi güvenliği süreçlerinin sağlanması"]},{"title":"Kişisel Verilerin Aktarılması","paragraphs":["Kişisel verileriniz ilgili mevzuat hükümleri çerçevesinde aşağıdaki kişi ve kuruluşlara aktarılabilmektedir."],"bullets":["Yetkili kamu kurum ve kuruluşlarına","İş ortaklarına","Konaklama ve ulaşım hizmet sağlayıcılarına","Teknoloji altyapı hizmet sağlayıcılarına","Hukuken yetkili kişi ve kurumlara"]},{"title":"Veri Sahibinin Hakları","paragraphs":["KVKK''nın 11. maddesi kapsamında veri sahipleri aşağıdaki haklara sahiptir."],"bullets":["Kişisel verilerinin işlenip işlenmediğini öğrenme","İşlenen verilere ilişkin bilgi talep etme","İşleme amacını öğrenme","Yanlış veya eksik işlenen verilerin düzeltilmesini isteme","Verilerin silinmesini veya yok edilmesini talep etme","İşlemenin hukuka uygunluğunu sorgulama","Zarara uğraması halinde tazminat talep etme"]}]}'::jsonb,'1.0',null,'published'::public.content_status,'{"title":"KVKK Aydınlatma Metni","description":"Kişisel Verilerin Korunması ve İşlenmesine İlişkin Aydınlatma Metni"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,document_key) do update set title=excluded.title,slug=excluded.slug,body_json=excluded.body_json,version=excluded.version,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.legal_documents (document_key,locale,title,slug,body_json,version,effective_date,status,seo_json,published_at) values ('privacy-policy','tr','Gizlilik Politikası','gizlilik-politikasi','{"headline":"Bilgileriniz Bizim İçin Değerlidir","sections":[{"title":null,"paragraphs":["SD Kongre, web sitesini ziyaret eden kullanıcıların ve hizmetlerinden yararlanan müşterilerinin kişisel bilgilerinin güvenliğini sağlamayı temel ilkelerinden biri olarak kabul etmektedir.","Web sitemiz üzerinden paylaşılan bilgiler yalnızca hizmet sunulması, iletişim faaliyetlerinin yürütülmesi, organizasyon süreçlerinin yönetilmesi ve yasal yükümlülüklerin yerine getirilmesi amacıyla kullanılmaktadır."]},{"title":"Toplanan Bilgilerin Korunması","bullets":["Yetkisiz erişime karşı korunur","Güvenli sistemlerde saklanır","Üçüncü kişilerle izinsiz paylaşılmaz","Yasal zorunluluklar dışında aktarılmaz"],"paragraphs":["SD Kongre, kişisel verilerin korunmasına ilişkin tüm teknik ve idari tedbirleri uygulamayı taahhüt eder."]},{"title":"Veri Güvenliği","paragraphs":["Kurumumuz aşağıdaki uygulamalarla verilerinizin korunmasını sağlamaktadır."],"bullets":["SSL güvenlik sertifikaları","Güncel güvenlik altyapıları","Erişim yetkilendirme sistemleri","Veri yedekleme uygulamaları","Düzenli güvenlik kontrolleri"]}]}'::jsonb,'1.0',null,'published'::public.content_status,'{"title":"Gizlilik Politikası","description":"Bilgileriniz Bizim İçin Değerlidir"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,document_key) do update set title=excluded.title,slug=excluded.slug,body_json=excluded.body_json,version=excluded.version,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.legal_documents (document_key,locale,title,slug,body_json,version,effective_date,status,seo_json,published_at) values ('cookie-policy','tr','Çerez (Cookie) Politikası','cerez-politikasi','{"headline":"Çerez Kullanımı Hakkında Bilgilendirme","sections":[{"title":null,"paragraphs":["Bu web sitesi kullanıcı deneyimini geliştirmek, site performansını analiz etmek ve sunulan hizmetleri iyileştirmek amacıyla çerezler kullanmaktadır.","Çerezler, ziyaret ettiğiniz internet sitesi tarafından cihazınıza kaydedilen küçük veri dosyalarıdır."]},{"title":"Zorunlu Çerezler","paragraphs":["Web sitesinin temel işlevlerinin çalışabilmesi için gereklidir."]},{"title":"Performans ve Analitik Çerezleri","paragraphs":["Kullanıcıların web sitesini nasıl kullandığına ilişkin anonim veriler sağlar."]},{"title":"İşlevsel Çerezler","paragraphs":["Tercihlerinizin hatırlanmasına yardımcı olur."]},{"title":"Pazarlama Çerezleri","paragraphs":["Sunulan içeriklerin ve reklamların ilgi alanlarınıza göre özelleştirilmesini sağlar."]},{"title":"Çerez Yönetimi","paragraphs":["Tarayıcı ayarlarınızı değiştirerek çerezleri silebilir, engelleyebilir veya kullanımını sınırlandırabilirsiniz.","Çerezleri devre dışı bırakmanız halinde web sitesinin bazı özelliklerinden tam olarak yararlanamayabilirsiniz."]}]}'::jsonb,'1.0',null,'published'::public.content_status,'{"title":"Çerez (Cookie) Politikası","description":"Çerez Kullanımı Hakkında Bilgilendirme"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,document_key) do update set title=excluded.title,slug=excluded.slug,body_json=excluded.body_json,version=excluded.version,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.legal_documents (document_key,locale,title,slug,body_json,version,effective_date,status,seo_json,published_at) values ('explicit-consent','tr','Açık Rıza Metni','acik-riza-metni','{"headline":"Açık Rıza Beyanı","sections":[{"title":null,"paragraphs":["6698 Sayılı Kişisel Verilerin Korunması Kanunu kapsamında tarafıma sunulan Aydınlatma Metni''ni okuduğumu ve anladığımı kabul ederim.","Bu kapsamda aşağıdaki verilerimin SD Kongre tarafından ilgili mevzuata uygun şekilde işlenmesine, saklanmasına ve gerekli durumlarda belirtilen üçüncü kişilerle paylaşılmasına özgür irademle açık rıza verdiğimi kabul ederim."],"bullets":["Kimlik bilgilerimin","İletişim bilgilerimin","Katılım ve kayıt bilgilerimin","Organizasyon süreçlerine ilişkin verilerimin","Görsel ve işitsel kayıtlarımın"]},{"title":null,"paragraphs":["Vermiş olduğum açık rızayı dilediğim zaman geri çekme hakkına sahip olduğumu biliyorum."]}]}'::jsonb,'1.0',null,'published'::public.content_status,'{"title":"Açık Rıza Metni","description":"Açık Rıza Beyanı"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,document_key) do update set title=excluded.title,slug=excluded.slug,body_json=excluded.body_json,version=excluded.version,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.legal_documents (document_key,locale,title,slug,body_json,version,effective_date,status,seo_json,published_at) values ('legal-basis','tr','Yasal Dayanaklar','yasal-dayanaklar','{"headline":"Kişisel Verilerin İşlenmesine İlişkin Hukuki Çerçeve","sections":[{"title":null,"paragraphs":["SD Kongre tarafından gerçekleştirilen tüm veri işleme faaliyetleri ulusal ve uluslararası mevzuat hükümlerine uygun şekilde yürütülmektedir."]},{"title":"Dayanak Alınan Mevzuatlar","items":[{"title":"6698 Sayılı Kişisel Verilerin Korunması Kanunu (KVKK)","description":"Kişisel verilerin işlenmesine ilişkin temel usul ve esasları belirlemektedir."},{"title":"Türk Borçlar Kanunu","description":"Müşteri ve hizmet sağlayıcı arasındaki sözleşmesel ilişkilerin yürütülmesine ilişkin hükümleri kapsar."},{"title":"Türk Ticaret Kanunu","description":"Ticari faaliyetler kapsamında tutulması gereken kayıtlar ve yükümlülükleri düzenler."},{"title":"Vergi Usul Kanunu","description":"Muhasebe ve mali kayıtların saklanmasıyla ilgili yükümlülükleri belirler."},{"title":"Elektronik Ticaretin Düzenlenmesi Hakkında Kanun","description":"Elektronik ortamda yürütülen iletişim ve ticari faaliyetlere ilişkin hükümleri düzenler."}]},{"title":"Veri İşleme Şartları","paragraphs":["Kişisel veriler aşağıdaki hukuki sebeplerinden en az birine dayanılarak işlenmektedir."],"bullets":["Kanunlarda açıkça öngörülmesi","Bir sözleşmenin kurulması veya ifası için gerekli olması","Hukuki yükümlülüklerin yerine getirilmesi","Bir hakkın tesisi, kullanılması veya korunması","İlgili kişinin açık rızasının bulunması"]},{"title":"Veri Saklama ve İmha","paragraphs":["Kişisel veriler, ilgili mevzuatta öngörülen süreler boyunca saklanmakta; saklama süresinin sona ermesi veya işleme amacının ortadan kalkması halinde güvenli yöntemlerle silinmekte, yok edilmekte veya anonim hale getirilmektedir."]}]}'::jsonb,'1.0',null,'published'::public.content_status,'{"title":"Yasal Dayanaklar","description":"Kişisel Verilerin İşlenmesine İlişkin Hukuki Çerçeve"}'::jsonb,'2026-08-04T00:00:00.000Z'::timestamptz) on conflict (locale,document_key) do update set title=excluded.title,slug=excluded.slug,body_json=excluded.body_json,version=excluded.version,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
